    def test_late_plan_cannot_borrow_action_or_finish_checkpoints(self):
        self.engine.setup(self.sid, checkpoints=["before_action", "finish"])
        self.apply_ready()
        original = copy.deepcopy(self.plan)
        replacement = copy.deepcopy(original)
        replacement["plan_id"] = "fictional-replacement-b"
        replacement["actions"][0]["action_id"] = "fictional-new-action-b"
        self.engine._validate_plan_document(self.state(), replacement)
        before = self.state()
        with self.assertRaises(WorkflowRefusal):
            self.engine.register_plan(self.sid, plan=replacement)
        self.assertEqual(self.state(), before)
        checkpoint = self.engine.resolve(self.sid)["data"]["pending"][0]
        self.engine.resolve(self.sid, pending_id=checkpoint["pending_id"], choice="continue", owner_quote="Continue only the original exact action A.", owner_message_id="fictional-original-action-checkpoint")
        self.finish(self.begin())
        self.engine.advance_stage(self.sid, evidence_ids=[])
        before = self.state()
        with self.assertRaises(WorkflowRefusal):
            self.engine.register_plan(self.sid, plan=replacement)
        self.assertEqual(self.state(), before)
        verification = self.evidence("verification", {"verification_passed": True, "checked_action_ids": ["fictional-action"], "plan_sha256": self.plan_hash})
        self.engine.advance_stage(self.sid, evidence_ids=[verification])
        before = self.state()
        with self.assertRaises(WorkflowRefusal):
            self.engine.register_plan(self.sid, plan=replacement)
        self.assertEqual(self.state(), before)
        finish = self.engine.resolve(self.sid)["data"]["pending"][0]
